import{_ as i,o as a,c as o,a3 as n}from"./chunks/framework.B8RmvCYz.js";const e="/ems_simulate/doc-img/point/simulation/1.png",l="/ems_simulate/doc-img/point/simulation/2.png",g=JSON.parse('{"title":"测点模拟 (Point Simulation)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/point/simulation.md","filePath":"guide/point/simulation.md","lastUpdated":1771156457000}'),r={name:"guide/point/simulation.md"};function s(p,t,m,u,_,d){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="测点模拟-point-simulation" tabindex="-1">测点模拟 (Point Simulation) <a class="header-anchor" href="#测点模拟-point-simulation" aria-label="Permalink to &quot;测点模拟 (Point Simulation)&quot;">​</a></h1><p>EMS Simulate 支持对测点值进行动态模拟，方便测试上位机的监控报警功能。</p><h2 id="_1-模拟原理" tabindex="-1">1. 模拟原理 <a class="header-anchor" href="#_1-模拟原理" aria-label="Permalink to &quot;1. 模拟原理&quot;">​</a></h2><p>开启模拟后，系统会根据预设的规则自动更新测点的值。支持的模拟类型包括：</p><ul><li><strong>随机数</strong> (Random)：在指定范围内生成随机值。</li><li><strong>递增</strong> (Increment)：按固定步长递增。</li><li><strong>递减</strong> (Decrement)：按固定步长递减。</li><li><strong>正弦波</strong> (Sine)：按正弦曲线变化。</li></ul><h2 id="_2-配置模拟" tabindex="-1">2. 配置模拟 <a class="header-anchor" href="#_2-配置模拟" aria-label="Permalink to &quot;2. 配置模拟&quot;">​</a></h2><p>打开测点的下拉抽屉，选择仿真模拟，进入模拟配置界面。</p><p><img src="'+e+'" alt=""></p><p>选择模拟类型并设置参数（此设置只针对单个测点）：</p><ul><li><strong>最小值/最大值</strong>：限制数值范围。</li><li><strong>步长</strong>：每次变化的幅度。</li><li><strong>周期</strong>：正弦波的周期（秒）。</li></ul><h2 id="_3-启动与停止" tabindex="-1">3. 启动与停止 <a class="header-anchor" href="#_3-启动与停止" aria-label="Permalink to &quot;3. 启动与停止&quot;">​</a></h2><p>配置完成后，点击“开始模拟”。此时测点值将按照规则自动变化。关闭模拟开关即可停止更新。</p><p><img src="'+l+'" alt=""></p><p>注意事项：最上方的模拟针对于所有测点，当更改过某个测点的模拟方式之后，该测点按照测点本身模拟方式进行模拟。</p>',14)])])}const h=i(r,[["render",s]]);export{g as __pageData,h as default};
